examples.template:
Column(verticalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space3)) {
    MonarchTableToolbar(
        resultCount = shown.size,
        search = {
            MonarchSearchBar(query = query, onQueryChange = { query = it }, onSearch = {}, placeholder = "Search...")
        },
        filters = {
            MonarchButton(text = {{filter}}, onClick = {}, variant = MonarchButtonVariant.Secondary, size = MonarchButtonSize.Sm)
        },
    ) {
        MonarchSegmentedControl(
            options = listOf({{viewLabels.0}}, {{viewLabels.1}}),
            selectedIndex = viewIds.indexOf(view),
            onSelect = { view = viewIds[it] },
            size = MonarchSegmentedControlSize.Sm,
        )
        MonarchButton(text = {{columnsLabel}}, onClick = {}, variant = MonarchButtonVariant.Secondary, size = MonarchButtonSize.Sm)
        MonarchButton(text = {{action}}, onClick = {}, variant = MonarchButtonVariant.Secondary, size = MonarchButtonSize.Sm)
    }
    MonarchDataTable(
        caption = {{caption}},
        rows = shown,
        columns = listOf(
            MonarchDataTableColumn<DomainRow>(title = {{columns.0}}, hideable = false) { it.name },
            MonarchDataTableColumn<DomainRow>(title = {{columns.1}}) { it.status },
            MonarchDataTableColumn<DomainRow>(title = {{columns.2}}) { it.owner },
        ),
        rowKey = { it.id },
        selection = selected,
        onSelectionChange = { selected = it },
        layout = MonarchDataTableLayout.Table,
    )
}

