examples.setup:
var query by remember { mutableStateOf("") }
val viewIds = listOf("table", "board")
var view by remember { mutableStateOf(viewIds[0]) }
var selected by remember { mutableStateOf(emptySet<String>()) }
data class DomainRow(val id: String, val name: String, val status: String, val owner: String)
val domains = listOf(
    DomainRow("1", "example.com", "Active", "Sam Lee"),
    DomainRow("2", "example.org", "Expiring", "Ana Ruiz"),
    DomainRow("3", "example.net", "Active", "Kai Moreau"),
)
val shown = domains.filter { query.isEmpty() || it.name.contains(query.lowercase()) }

examples.code:
Column(verticalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space3)) {
    MonarchTableToolbar(
        resultCount = shown.size,
        search = {
            MonarchSearchBar(query = query, onQueryChange = { query = it }, onSearch = {}, placeholder = "Search...")
        },
        filters = {
            MonarchButton(text = "Status", onClick = {}, variant = MonarchButtonVariant.Secondary, size = MonarchButtonSize.Sm)
        },
    ) {
        MonarchSegmentedControl(
            options = listOf("Table", "Board"),
            selectedIndex = viewIds.indexOf(view),
            onSelect = { view = viewIds[it] },
            size = MonarchSegmentedControlSize.Sm,
        )
        MonarchButton(text = "Columns", onClick = {}, variant = MonarchButtonVariant.Secondary, size = MonarchButtonSize.Sm)
        MonarchButton(text = "New domain", onClick = {}, variant = MonarchButtonVariant.Secondary, size = MonarchButtonSize.Sm)
    }
    MonarchDataTable(
        caption = "Domains",
        rows = shown,
        columns = listOf(
            MonarchDataTableColumn<DomainRow>(title = "Name", hideable = false) { it.name },
            MonarchDataTableColumn<DomainRow>(title = "Status") { it.status },
            MonarchDataTableColumn<DomainRow>(title = "Owner") { it.owner },
        ),
        rowKey = { it.id },
        selection = selected,
        onSelectionChange = { selected = it },
        layout = MonarchDataTableLayout.Table,
    )
}

